#include <stdio.h>
#include <string.h>
#include <ctype.h>

/*
 * Roman numeral parser – reproduces the behaviour of prog29_roman_numeral_parser.
 * It accepts a single command‑line argument, validates that it is a canonical
 * Roman numeral (uppercase, length ≤ 63, value ≤ 3999) and prints the integer
 * value.  Any invalid input results in the exact output "INVALID\n".
 */

static const char *SYMS[] = {
    "M",  "CM", "D",  "CD", "C",  "XC", "L",  "XL",
    "X",  "IX", "V",  "IV", "I"
};
static const int VALUES[] = {
    1000, 900, 500, 400, 100, 90, 50, 40,
    10,   9,   5,   4,   1
};

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("INVALID");
        return 0;
    }

    const char *in = argv[1];
    size_t len = strlen(in);
    if (len == 0 || len > 63) {
        puts("INVALID");
        return 0;
    }

    char upper[64];
    for (size_t i = 0; i < len; ++i) {
        char c = in[i];
        if ('a' <= c && c <= 'z')
            c = (char)toupper((unsigned char)c);
        else
            c = (char)toupper((unsigned char)c); // also normalises any other case
        if (c!='I' && c!='V' && c!='X' && c!='L' && c!='C' && c!='D' && c!='M') {
            puts("INVALID");
            return 0;
        }
        upper[i] = c;
    }
    upper[len] = '\0';

    /* Parse the numeral, accumulating the value and advancing a cursor. */
    int value = 0;
    size_t pos = 0;
    for (size_t idx = 0; idx < sizeof(SYMS)/sizeof(SYMS[0]); ++idx) {
        size_t sym_len = strlen(SYMS[idx]);
        while (pos + sym_len <= len && strncmp(upper + pos, SYMS[idx], sym_len) == 0) {
            value += VALUES[idx];
            pos += sym_len;
        }
    }
    if (pos != len) {               // leftover characters – not a valid numeral
        puts("INVALID");
        return 0;
    }
    if (value > 3999) {             // out of range for standard Roman numerals
        puts("INVALID");
        return 0;
    }

    /* Re‑construct the canonical representation of the computed value and
       compare it with the original (already upper‑cased) input. */
    char canonical[64];
    size_t cpos = 0;
    int remaining = value;
    for (size_t idx = 0; idx < sizeof(SYMS)/sizeof(SYMS[0]); ++idx) {
        while (remaining >= VALUES[idx]) {
            size_t sym_len = strlen(SYMS[idx]);
            memcpy(canonical + cpos, SYMS[idx], sym_len);
            cpos += sym_len;
            remaining -= VALUES[idx];
        }
    }
    canonical[cpos] = '\0';
    if (strcmp(canonical, upper) != 0) {
        puts("INVALID");
        return 0;
    }

    printf("%d\n", value);
    return 0;
}
